/**
 *  One product event the app may send, with its field names (for "What's
 *  collected"). Generated from the core's typed event list.
 */
export type TelemetryEventInfo = {
	name: string,
	fields: string[],
};

/**
 *  The two sharing choices. `None` until the user chose (onboarding or
 *  Settings); nothing leaves the machine before that.
 */
export type TelemetryStatus = {
	/**  A usage-data sink (product events) is configured in this build. */
	usage_available: boolean,
	/**  An error-report sink (warnings, errors, traces) is configured. */
	errors_available: boolean,
	/**  "Share anonymous usage data". */
	usage: boolean | null,
	/**  "Send error reports". */
	errors: boolean | null,
	/**  Every product event and its fields. */
	events: TelemetryEventInfo[],
	/**  What is never sent, one line each. */
	never_sent: string[],
};

export type Thread = {
	id: ThreadId,
	anchor: Anchor | null,
	resolved: boolean,
	outdated: boolean,
	comments: Comment[],
};

export type ThreadId = string;

export type ToastLevel = "info" | "warn" | "error";

export type TokenSource = "keychain" | "gh" | "env" | "none" |
/**  The simulated sandbox host (docs/sandbox.md): no real token at all. */
"sandbox";

export type Transaction = {
	/**  Client-generated, for de-duplication on retry. */
	id: string,
	ops: MutationOp[],
};

export type TransactionResult = { status: "ok"; last_sync_id: number } |
/**  Rejected by domain validation; the UI rolls back. */
{ status: "rejected"; reason: string };

export type TriageAction =
/**  The viewer takes the review themselves. */
{ action: "take" } |
/**  The viewer declines; the inbox row is marked done. */
{ action: "decline" } |
/**  Hand the review to someone else (logins). */
{ action: "reassign"; to: string[] };

export type TriageRequest = {
	pr: PrId,
	action: TriageAction,
};

/**
 *  A product event the UI reports (`track_ui`). Typed like the core's own:
 *  the core accepts only known values and drops anything else.
 */
export type UiEvent =
/**
 *  An onboarding step was shown: `account`, `telemetry`, `github`,
 *  `agents`, `projects`, `done`.
 */
{ event: "onboarding_step"; step: string };

export type UpdateInfo = {
	version: string,
	notes: string,
	downloaded: boolean,
};

export type ViewedState = "unviewed" | "viewed" |
/**  Was viewed, then the file changed. */
"dismissed";

export type WireAction = {
	id: number,
	model: string,
	model_id: string,
	action: SyncCode,
	data: unknown | null,
};

export type WireRow = {
	model: string,
	id: string,
	data: unknown,
	archived: boolean,
};
